"""NOTICE.md names every tracked binary and generated file (plan task S0-T02). Needs neither the library nor a GPU."""
from __future__ import annotations

import hashlib
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
NOTICE = (ROOT / "NOTICE.md").read_text(encoding="utf-8")


def test_every_cubin_is_listed_with_its_hash():
    cubins = sorted((ROOT / "cubins").glob("*.cubin"))
    assert cubins, "no cubins found"
    for path in cubins:
        digest = hashlib.sha256(path.read_bytes()).hexdigest()
        assert f"`cubins/{path.name}` | `{digest}`" in NOTICE, path.name


def test_every_generated_source_is_listed():
    generated = sorted(p for p in (ROOT / "src").iterdir() if p.name.startswith("generated_"))
    marked = sorted(p for p in (ROOT / "src").iterdir()
                    if p.is_file() and "Auto-generated by" in p.read_text(encoding="utf-8", errors="replace")[:400])
    assert generated == marked, "a generated file lacks the generated_ prefix, or the reverse"
    for path in generated:
        assert f"`src/{path.name}`" in NOTICE, path.name


def test_licence_texts_are_present():
    assert (ROOT / "LICENSE").read_text(encoding="utf-8").startswith("MIT License")
    assert "BSD-3-Clause" in (ROOT / "cubins" / "LICENSE.cutlass").read_text(encoding="utf-8")
    listed = set(re.findall(r"`(cubins/[^`]+\.cubin)`", NOTICE))
    assert listed == {f"cubins/{p.name}" for p in (ROOT / "cubins").glob("*.cubin")}
